// Convert decimal number to binary number

function decimalToBinary(decNum) {
  var binaryNum = 0;

  // Calculate the binary number
  while (decNum > 0) {
    var remainder = decNum % 2;
    decNum = Math.floor(decNum / 2);
    binaryNum = binaryNum * 10 + remainder;
  }

  return binaryNum;
}

// Test the function
console.log(decimalToBinary(8));
console.log(decimalToBinary(10));
console.log(decimalToBinary(15));
```

