def max_sum(input_list):
    max_sum = 0
    for i in range(len(input_list)):
        for j in range(i+1, len(input_list)):
            sum = input_list[i] + input_list[j]
            if sum > max_sum:
                max_sum = sum
    return max_sum

max_sum([1, 2, -8, 9, 5])
